(function(){'use strict';if(window.MwTripLog)return;var KEY='mw-trip-log-queue';var API='/crm/api/trip-report.php';var flushing=!1;function csrf(){if(window.MW_CSRF_TOKEN)return window.MW_CSRF_TOKEN;var el=document.querySelector('input[name="csrf_token"]');return el?el.value:''}
function readQueue(){try{return JSON.parse(localStorage.getItem(KEY)||'[]')||[]}catch(e){return[]}}
function writeQueue(q){try{localStorage.setItem(KEY,JSON.stringify(q));return!0}catch(e){return!1}}
function mine(userId){return readQueue().filter(function(i){return i.userId===userId&&!i.rejection})}
function post(fields,performedAt){var body=new FormData();Object.keys(fields).forEach(function(k){if(fields[k]!==undefined&&fields[k]!==null)body.append(k,fields[k]);});body.set('csrf_token',csrf());body.set('performed_at',String(performedAt));return fetch(API,{method:'POST',credentials:'same-origin',body:body}).then(function(r){if(r.status===401||r.status===403||r.status>=500)throw new Error('unavailable:'+r.status);return r.json().then(function(data){return{ok:r.ok&&data&&data.success,data:data||{}}})})}
function enqueue(userId,action,fields,performedAt){var q=readQueue();q.push({id:String(Date.now())+Math.random().toString(16).slice(2),userId:userId,action:action,fields:fields,performedAt:performedAt,rejection:null});return writeQueue(q)}
function flush(userId){if(flushing||!userId)return Promise.resolve(0);var pending=mine(userId);if(!pending.length)return Promise.resolve(0);flushing=!0;var filed=0;function next(){var item=mine(userId)[0];if(!item)return Promise.resolve();var fields=Object.assign({},item.fields,{action:item.action});if(item.action==='save_post_trip')fields.confirm_odometer='1';return post(fields,item.performedAt).then(function(res){var q=readQueue();if(res.ok){writeQueue(q.filter(function(i){return i.id!==item.id}));filed++;return next()}
q.forEach(function(i){if(i.id===item.id)i.rejection=res.data.error||'The server did not accept this entry.'});writeQueue(q)})}
return next().catch(function(){}).then(function(){flushing=!1;notify(userId);return filed})}
function submit(action,fields,userId){var performedAt=Date.now();fields=Object.assign({},fields,{action:action});delete fields.csrf_token;return flush(userId).then(function(){if(mine(userId).length){enqueue(userId,action,fields,performedAt);notify(userId);return{status:'queued'}}
return post(fields,performedAt).then(function(res){if(res.ok)return{status:'filed',data:res.data};return{status:'rejected',message:res.data.error||'Could not save.',code:res.data.code||null}},function(){enqueue(userId,action,fields,performedAt);notify(userId);return{status:'queued'}})})}
function notify(userId){document.dispatchEvent(new CustomEvent('mw-trip-log-changed',{detail:{waiting:mine(userId).length,rejected:readQueue().filter(function(i){return i.userId===userId&&i.rejection})}}))}
var GREEN='var(--mw-green, var(--hb-green, var(--al-green, var(--dl-green, green))))';function ask(){return new Promise(function(resolve){var wrap=document.createElement('div');wrap.setAttribute('role','dialog');wrap.setAttribute('aria-modal','true');wrap.style.cssText='position:fixed;inset:0;z-index:100000;display:flex;align-items:flex-end;justify-content:center;background:rgba(0,0,0,.55);';var btn='display:block;width:100%;padding:15px;margin-top:10px;border-radius:999px;font-size:16px;font-weight:700;';wrap.innerHTML='<div style="width:100%;max-width:520px;background:Canvas;color:CanvasText;border-radius:20px 20px 0 0;padding:26px 22px calc(22px + env(safe-area-inset-bottom));text-align:center;">'+'<h2 style="font-size:20px;margin:0 0 10px;">Are you driving a company vehicle this shift?</h2>'+'<p style="font-size:14px;opacity:.75;margin:0 0 16px;line-height:1.45;">The driver has to inspect the vehicle before it moves and log the trip — it\'s a legal requirement. If you\'re riding along, you don\'t. You can change this later if you take over the wheel.</p>'+'<button type="button" data-a="yes" style="'+btn+'border:0;color:white;background:'+GREEN+';">Yes, I\'m driving</button>'+'<button type="button" data-a="no" style="'+btn+'background:transparent;color:inherit;border:1px solid currentColor;opacity:.85;">No, I\'m not driving</button>'+'</div>';wrap.addEventListener('click',function(e){var a=e.target&&e.target.getAttribute&&e.target.getAttribute('data-a');if(!a)return;document.body.removeChild(wrap);resolve(a==='yes')});document.body.appendChild(wrap)})}
function afterClockIn(res,userId){res=res||{};if(res.pre_trip_required)return Promise.resolve('/crm/driver-log.php');if(!res.driver_question_required)return Promise.resolve(null);return ask().then(function(driving){if(driving)return'/crm/driver-log.php';return submit('declare',{driving:'0'},userId).then(function(){return null})})}
window.MwTripLog={submit:submit,flush:flush,afterClockIn:afterClockIn,waiting:function(userId){return mine(userId).length},rejected:function(userId){return readQueue().filter(function(i){return i.userId===userId&&i.rejection})},discardRejected:function(userId){writeQueue(readQueue().filter(function(i){return!(i.userId===userId&&i.rejection)}));notify(userId)}};function auto(){if(window.MW_USER_ID)flush(window.MW_USER_ID);}
window.addEventListener('online',auto);document.addEventListener('visibilitychange',function(){if(!document.hidden)auto();});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',auto);else auto()}())